{"experiments":[
  {
    "hypothesis":"Patients with higher tumor mutation burden exhibit increased expression of key immune checkpoint and T-cell marker genes (PDCD1, CD274, CTLA4, CD8A).",
    "experiment_plan":{
      "objective":"Quantify correlation between per-patient TMB and expression levels of selected immune marker genes to assess immunogenicity.",
      "steps":"1. Load cleaned_clinical_data.csv and cleaned_mutations.csv. 2. Compute TMB: count total somatic mutations per bcr_patient_barcode. 3. Load cleaned_gene_expression.csv, remove Ensembl version suffix, and extract rows for PDCD1, CD274, CTLA4, CD8A by matching known Ensembl IDs. 4. Merge TMB and gene expression for each patient. 5. For each gene, compute Spearman rank correlation coefficient and p-value between TMB and expression. 6. Adjust p-values for multiple testing (e.g., Benjamini–Hochberg). 7. Create scatter plots with regression lines for each gene vs TMB.",
      "deliverables":"Table of Spearman rho and adjusted p-values for each gene; four scatter plots with regression overlays; brief interpretation noting which genes, if any, show significant positive correlation with TMB."
    }
  },
  {
    "hypothesis":"Breast cancer patients harboring TP53 mutations have shorter overall survival compared to TP53 wild-type patients.",
    "experiment_plan":{
      "objective":"Test the impact of TP53 mutation status on overall survival using survival analysis.",
      "steps":"1. Load cleaned_clinical_data.csv and cleaned_mutations.csv. 2. Identify patients with any TP53 mutation (Hugo_Symbol=='TP53') and label others as wild-type. 3. From clinical data, define overall survival time as days_to_death if vital_status=='Dead', else days_to_last_followup, and event indicator (1 if Dead, 0 if Alive). 4. Build a survival object stratified by TP53 mutant vs wild-type. 5. Plot Kaplan–Meier curves for both groups. 6. Perform log-rank test to compare survival curves.",
      "deliverables":"Kaplan–Meier plot of overall survival by TP53 status; log-rank test statistic and p-value; group sample sizes and median survival times."
    }
  },
  {
    "hypothesis":"PIK3CA and TP53 mutations occur less frequently together than expected by chance (mutual exclusivity).",
    "experiment_plan":{
      "objective":"Determine co-occurrence or mutual exclusivity of PIK3CA and TP53 mutations across patients.",
      "steps":"1. Load cleaned_mutations.csv. 2. For each patient, create binary flags: PIK3CA_mut (any mutation in Hugo_Symbol=='PIK3CA') and TP53_mut (any mutation in Hugo_Symbol=='TP53'). 3. Construct a 2×2 contingency table of PIK3CA_mut vs TP53_mut. 4. Perform Fisher’s exact test to evaluate enrichment or depletion of co-occurrence. 5. Compute odds ratio and 95% confidence interval.",
      "deliverables":"Contingency table counts; Fisher’s exact test p-value; odds ratio with confidence interval; interpretation of mutual exclusivity or co-occurrence."
    }
  },
  {
    "hypothesis":"Premenopausal breast cancer patients have higher tumor expression of the aromatase gene CYP19A1 compared to postmenopausal patients.",
    "experiment_plan":{
      "objective":"Compare CYP19A1 expression between pre- and postmenopausal groups to assess hormone metabolism differences.",
      "steps":"1. Load cleaned_clinical_data.csv and select bcr_patient_barcode and menopause_status. 2. Filter to patients labeled 'Pre' and 'Post' in menopause_status. 3. Load cleaned_gene_expression.csv, remove version suffix, and locate the Ensembl ID for CYP19A1. 4. Extract CYP19A1 expression per patient. 5. Merge expression with menopause status. 6. Use Mann–Whitney U test to compare distributions. 7. Generate a boxplot of CYP19A1 expression by group.",
      "deliverables":"Summary table (count, mean, median, IQR) of CYP19A1 by menopause_status; Mann–Whitney U statistic and p-value; boxplot; conclusion about expression differences."
    }
  },
  {
    "hypothesis":"Patients who received radiation therapy have higher tumor mutation burden than those who did not receive radiation.",
    "experiment_plan":{
      "objective":"Assess whether radiation therapy exposure is associated with elevated TMB.",
      "steps":"1. Load cleaned_clinical_data.csv, extract bcr_patient_barcode and radiation_therapy (YES/NO). 2. Load cleaned_mutations.csv and compute TMB per patient. 3. Merge TMB with radiation_therapy labels. 4. Compare TMB distributions using Mann–Whitney U test and two-sample t-test (unequal variance). 5. Plot TMB by radiation_therapy group as boxplot or violin plot.",
      "deliverables":"Table of TMB summary (mean, median, IQR) by radiation group; Mann–Whitney U and t-test results; boxplot; interpretation of association."
    }
  },
  {
    "hypothesis":"Patients with lymph node–positive disease (pathologic_n != 'N0') exhibit higher tumor mutation burden than node-negative patients.",
    "experiment_plan":{
      "objective":"Test association between lymph node involvement and TMB.",
      "steps":"1. Load cleaned_clinical_data.csv, select bcr_patient_barcode and pathologic_n. 2. Categorize patients into node_negative (pathologic_n=='N0') vs node_positive (all other codes). 3. Load cleaned_mutations.csv and compute TMB. 4. Merge TMB with node status. 5. Compare TMB distributions with Mann–Whitney U test. 6. Create boxplot of TMB by node status.",
      "deliverables":"Summary statistics of TMB by node status; Mann–Whitney U statistic and p-value; boxplot; conclusion on whether node positivity correlates with higher TMB."
    }
  },
  {
    "hypothesis":"Unsupervised clustering of the top 1000 most variable genes identifies patient subgroups with distinct overall survival outcomes.",
    "experiment_plan":{
      "objective":"Discover molecular subtypes via clustering on expression and evaluate their prognostic significance.",
      "steps":"1. Load cleaned_gene_expression.csv and compute variance per gene across samples. 2. Select top 1000 genes by variance. 3. Standardize expression values (z-score) across patients. 4. Perform PCA for dimensionality reduction (e.g., top 10 PCs) and then k-means clustering (k=3). 5. Assign cluster labels to each patient. 6. Load cleaned_clinical_data.csv, derive overall survival time and event as before. 7. Plot Kaplan–Meier curves for each cluster and perform log-rank test across clusters.",
      "deliverables":"Cluster membership for each patient; PCA scatterplot colored by cluster; Kaplan–Meier plot for clusters; log-rank test p-value; cluster sizes and median survival times."
    }
  },
  {
    "hypothesis":"Breast tumors treated with neoadjuvant therapy have higher expression of the proliferation marker MKI67 compared to untreated tumors.",
    "experiment_plan":{
      "objective":"Compare MKI67 expression between neoadjuvant-treated and untreated patients to assess proliferation differences.",
      "steps":"1. Load cleaned_clinical_data.csv, extract bcr_patient_barcode and neoadjuvant_treatment (Yes/No). 2. Load cleaned_gene_expression.csv, remove version suffix, and locate the Ensembl ID for MKI67. 3. Extract MKI67 expression per patient. 4. Merge expression with neoadjuvant_treatment labels. 5. Use Mann–Whitney U test to compare MKI67 distributions. 6. Generate boxplot of MKI67 by treatment status.",
      "deliverables":"Table of MKI67 summary (count, mean, median, IQR) by neoadjuvant treatment; Mann–Whitney U statistic and p-value; boxplot; interpretation of proliferation differences."
    }
  }
]}
